191	                ->where('site_id', $site->id)
192	                ->where('pool', SiteMedia::POOL_DESIGN)
193	                ->where('purpose', SiteMedia::PURPOSE_PLACEHOLDER)
194	                ->whereNull('deleted_at')
195	                ->orderBy('sort_order')
196	                ->lockForUpdate()
197	                ->get();
198	
199	            $offset = self::PLACEHOLDER_MAX + 1000;
200	            foreach ($remaining as $idx => $r) {
201	                SiteMedia::query()->where('id', $r->id)->update(['sort_order' => $offset + $idx]);
202	            }
203	            foreach ($remaining as $idx => $r) {
204	                SiteMedia::query()->where('id', $r->id)->update(['sort_order' => $idx]);
