323	    private function assertMimeAllowed(string $actual): void
324	    {
325	        if (! in_array($actual, self::ALLOWED_IMAGE_MIMES, true)) {
326	            throw new UnprocessableImageException(
327	                "Rejected: MIME type '{$actual}' is not an accepted image format."
328	            );
329	        }
