332	    private function purposeForLogoVariant(string $variant): string
333	    {
334	        return match ($variant) {
335	            'full' => SiteMedia::PURPOSE_LOGO_FULL,
336	            'square' => SiteMedia::PURPOSE_LOGO_SQUARE,
337	            default => throw new \InvalidArgumentException("Unknown logo variant: {$variant}"),
338	        };
339	    }
