341	    private function createDesignRow(Site $site, string $purpose, ?string $mime, ?int $size, int $sortOrder): SiteMedia
342	    {
343	        return DB::transaction(function () use ($site, $purpose, $mime, $size, $sortOrder) {
344	            // Singleton-replace: soft-delete any prior active row with this purpose.
345	            SiteMedia::query()
346	                ->where('site_id', $site->id)
347	                ->where('pool', SiteMedia::POOL_DESIGN)
348	                ->where('purpose', $purpose)
349	                ->whereNull('deleted_at')
350	                ->lockForUpdate()
351	                ->get()
352	                ->each(fn (SiteMedia $row) => $row->delete());
353	
354	            return SiteMedia::create([
355	                'site_id' => $site->id,
356	                'pool' => SiteMedia::POOL_DESIGN,
357	                'purpose' => $purpose,
358	                'path' => '',
359	                'sort_order' => $sortOrder,
360	                'is_active' => true,
361	                'media_type' => SiteMedia::MEDIA_TYPE_IMAGE,
362	                'processing_state' => SiteMedia::PROCESSING_STATE_PENDING,
363	                'original_mime' => $mime,
364	                'original_size_bytes' => $size,
365	            ]);
366	        });
367	    }
