435	    private function extensionFromMime(string $mime): string
436	    {
437	        return match (strtolower(trim(explode(';', $mime)[0] ?? ''))) {
438	            'image/png' => 'png',
439	            'image/jpeg', 'image/jpg' => 'jpg',
440	            'image/webp' => 'webp',
441	            'image/svg+xml' => 'svg',
442	            'image/gif' => 'gif',
443	            default => 'png',
444	        };
445	    }
